function headersFor(asset) {
  if (asset.immutable) {
    // hashed filename means content changing implies a new URL — cache forever
    return { 'Cache-Control': 'public, max-age=31536000, immutable' };
  }
  return { 'Cache-Control': 'public, max-age=300' };  // revalidate every 5 min
}

// PoP pseudocode, not app code — shown to make the miss path concrete:
async function servePoP(req) {
  const cached = cache.get(req.url);
  if (cached && !cached.expired) return cached;      // cache hit: no origin call

  const fresh = await fetchFromOrigin(req);           // cache miss: origin trip
  cache.set(req.url, fresh, fresh.headers['cache-control']);
  return fresh;
}

async function purge(urls) {
  return cdn.api.purge({ urls, priority: 'immediate' });
}

