const inflight = new Map();

async function fetchFromOriginCoalesced(url) {
  if (inflight.has(url)) return inflight.get(url);       // join existing fetch
  const p = doFetch(url).finally(() => inflight.delete(url));
  inflight.set(url, p);
  return p;
}
